// ─── Tab bar icons ───────────────────────────────────────────────────────────
// One system for all four: 24px grid, solid filled silhouettes with small
// negative-space cuts (done with masks). Inactive = muted tone, active = granate.
const GRANATE = '#7B1F3A'
const MUTED   = '#A08888'

function TabIcon({ active, children }: { active: boolean; children: ReactNode }) {
  return (
    <svg viewBox="0 0 24 24" width="24" height="24" aria-hidden
         fill={active ? GRANATE : MUTED}>
      {children}
    </svg>
  )
}

